import org.rabochaya.projects.*;import java.util.*;import org.w3c.dom.*;import java.io.*;import javax.xml.parsers.*;import javax.xml.transform.*;import javax.xml.transform.dom.DOMSource;import javax.xml.transform.stream.StreamResult;
public final class ObjectVisibilityTests {
 static int checks;static void check(boolean ok){checks++;if(!ok)throw new AssertionError("check "+checks);}
 static Element parse(String xml)throws Exception{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);return f.newDocumentBuilder().parse(new ByteArrayInputStream(xml.getBytes("UTF-8"))).getDocumentElement();}
 static String xml(Element e)throws Exception{StringWriter w=new StringWriter();TransformerFactory.newInstance().newTransformer().transform(new DOMSource(e),new StreamResult(w));return w.toString();}
 static void strip(Element e){for(Node n=e.getFirstChild();n!=null;){Node next=n.getNextSibling();if(n instanceof Element){Element c=(Element)n;if("visibility".equals(c.getLocalName())&&(c.getNamespaceURI()==null||c.getNamespaceURI().equals("http://www.opengis.net/kml/2.2")))e.removeChild(c);else strip(c);}n=next;}}
 static String content(Element e)throws Exception{Element copy=(Element)e.cloneNode(true);strip(copy);return xml(copy);}
 static void bad(Element root,Runnable r)throws Exception{String before=xml(root);boolean no=false;try{r.run();}catch(IllegalArgumentException|IllegalStateException e){no=true;}check(no);check(xml(root).equals(before));}
 static Element fixture()throws Exception{return parse("<Document xmlns='http://www.opengis.net/kml/2.2'><Folder id='folder'><name>F</name><visibility>false</visibility><Placemark id='one'><name>One</name><description><![CDATA[<a href='attachments/keep.bin'>keep</a>]]></description><Style id='style'/><MultiGeometry><LineString><altitudeMode>absolute</altitudeMode><coordinates>1,2,123 3,4,-7</coordinates></LineString><Polygon><outerBoundaryIs><LinearRing><coordinates>0,0 2,0 2,2 0,0</coordinates></LinearRing></outerBoundaryIs><innerBoundaryIs><LinearRing><coordinates>0.1,0.1 0.2,0.1 0.2,0.2 0.1,0.1</coordinates></LinearRing></innerBoundaryIs></Polygon></MultiGeometry></Placemark><Placemark id='two'><name>Two</name><visibility>0</visibility><Point/></Placemark><Folder><name>Nested</name><Placemark><visibility>1</visibility><Point/></Placemark></Folder></Folder><Placemark><name>Root</name><visibility>true</visibility><Point/></Placemark><Placemark><LineString/></Placemark></Document>");}
 public static void main(String[] args)throws Exception{
  Element root=fixture();String expected=ObjectTree.token(root),payload=content(root);check(!ObjectVisibility.own(ObjectTree.resolve(root,"0")));check(!ObjectVisibility.effective(ObjectTree.resolve(root,"0/0")));check(ObjectVisibility.own(ObjectTree.resolve(root,"0/0")));check(ObjectVisibility.own(ObjectTree.resolve(root,"1")));
  ObjectVisibility.Preview show=ObjectVisibility.preview(root,Arrays.asList("0"),true,expected);check(show.selected==1&&show.changed==1&&show.shown==4&&show.hidden==0&&show.selectedStillHidden==0);check(ObjectTree.token(root).equals(expected));ObjectVisibility.Preview child=ObjectVisibility.preview(root,Arrays.asList("0/0"),true,expected);check(child.changed==0&&child.shown==0&&child.selectedStillHidden==1);ObjectVisibility.apply(root,Arrays.asList("0/0"),true,expected);check(ObjectTree.token(root).equals(expected));
  ObjectVisibility.apply(root,Arrays.asList("0"),true,expected);check(ObjectVisibility.effective(ObjectTree.resolve(root,"0/0")));check(!ObjectVisibility.effective(ObjectTree.resolve(root,"0/1")));check(content(root).equals(payload));check(ObjectTree.resolve(root,"0/0").getElementsByTagNameNS("*","coordinates").item(0).getTextContent().equals("1,2,123 3,4,-7"));check(ObjectTree.resolve(root,"0/0").getAttribute("id").equals("one"));
  String shownToken=ObjectTree.token(root);ObjectVisibility.Preview hide=ObjectVisibility.apply(root,Arrays.asList("0"),false,shownToken);check(hide.changed==1&&hide.hidden==4&&hide.shown==0);check(!ObjectVisibility.effective(ObjectTree.resolve(root,"0/2/0")));check(content(root).equals(payload));
  root=fixture();final Element bothRoot=root;expected=ObjectTree.token(root);ObjectVisibility.Preview both=ObjectVisibility.apply(root,Arrays.asList("0","0/1","0"),true,expected);check(both.selected==2&&both.changed==2&&both.shown==5);check(ObjectVisibility.effective(ObjectTree.resolve(root,"0/1")));check(content(root).equals(payload));
  String current=ObjectTree.token(root);ObjectVisibility.Preview noOp=ObjectVisibility.apply(root,Arrays.asList("0","0/1"),true,current);check(noOp.changed==0&&noOp.shown==0&&noOp.hidden==0);check(ObjectTree.token(root).equals(current));
  final String stale=expected;bad(root,()->ObjectVisibility.apply(bothRoot,Arrays.asList("0"),false,stale));bad(root,()->ObjectVisibility.apply(bothRoot,Arrays.asList("1","99"),false,ObjectTree.token(bothRoot)));bad(root,()->ObjectVisibility.apply(bothRoot,Arrays.asList(""),true,ObjectTree.token(bothRoot)));bad(root,()->ObjectVisibility.apply(bothRoot,Arrays.asList("00"),true,ObjectTree.token(bothRoot)));bad(root,()->ObjectVisibility.apply(bothRoot,null,true,ObjectTree.token(bothRoot)));bad(root,()->ObjectVisibility.apply(bothRoot,Collections.<String>emptyList(),true,ObjectTree.token(bothRoot)));bad(root,()->ObjectVisibility.apply(bothRoot,Collections.nCopies(10001,"0"),false,ObjectTree.token(bothRoot)));
  Element duplicate=parse("<Document xmlns='http://www.opengis.net/kml/2.2'><Placemark><name>A</name></Placemark><Placemark><visibility>1</visibility><visibility>0</visibility></Placemark></Document>");check(!ObjectVisibility.own(ObjectTree.resolve(duplicate,"1")));bad(duplicate,()->ObjectVisibility.apply(duplicate,Arrays.asList("0","1"),false,ObjectTree.token(duplicate)));
  Element prefix=parse("<k:Document xmlns:k='http://www.opengis.net/kml/2.2' xmlns:x='urn:custom'><k:Placemark id='p'><k:name>P</k:name><x:visibility>0</x:visibility><k:description>keep</k:description><k:Point/></k:Placemark></k:Document>");Element p=ObjectTree.resolve(prefix,"0");check(ObjectVisibility.own(p));String original=content(prefix);ObjectVisibility.apply(prefix,Arrays.asList("0"),false,ObjectTree.token(prefix));check(!ObjectVisibility.own(p));Element visibility=(Element)p.getElementsByTagNameNS("http://www.opengis.net/kml/2.2","visibility").item(0);check(visibility.getPrefix().equals("k")&&visibility.getTextContent().equals("0"));check(p.getElementsByTagNameNS("urn:custom","visibility").getLength()==1);check(content(prefix).equals(original));check(((Element)p.getElementsByTagNameNS("http://www.opengis.net/kml/2.2","name").item(0)).getNextSibling()==visibility);
  Element ancestor=parse("<Document><visibility>0</visibility><Folder><visibility>0</visibility><Placemark/></Folder></Document>");ObjectVisibility.Preview blocked=ObjectVisibility.apply(ancestor,Arrays.asList("0"),true,ObjectTree.token(ancestor));check(blocked.changed==1&&blocked.shown==0&&blocked.selectedStillHidden==1);check(!ObjectVisibility.effective(ObjectTree.resolve(ancestor,"0/0")));check(ancestor.getElementsByTagName("visibility").item(0).getTextContent().equals("0"));
  for(String value:new String[]{"0","false"," false ","1","true","","invalid"}){Element e=parse("<Placemark><visibility>"+value+"</visibility></Placemark>");check(ObjectVisibility.own(e)==!(value.trim().equals("0")||value.trim().equals("false")));}
  Element old=parse("<Document xmlns='http://earth.google.com/kml/2.1'><Placemark><visibility>false</visibility></Placemark></Document>");check(!ObjectVisibility.own(ObjectTree.resolve(old,"0")));ObjectVisibility.apply(old,Arrays.asList("0"),true,ObjectTree.token(old));check(ObjectVisibility.own(ObjectTree.resolve(old,"0")));
  System.out.println("PASS ObjectVisibility: "+checks+" assertions");
 }
}
